-- The cache version of km_arabic: one row per family of tables. Any write to
-- a family's tables stamps its row (triggers below), so every writer — worker,
-- script or skill — moves the version, and payloads kept under the old one
-- (shared/src/swr.ts, the app's KMAPSCache) are rebuilt on their next read.
CREATE TABLE IF NOT EXISTS kmaps_cache_version (
  family     TEXT PRIMARY KEY,
  version    TEXT NOT NULL,
  updated_at TEXT NOT NULL
);
INSERT OR IGNORE INTO kmaps_cache_version (family, version, updated_at) VALUES ('content', strftime('%Y-%m-%dT%H:%M:%fZ','now'), datetime('now'));
CREATE TRIGGER IF NOT EXISTS trg_kcv_ar_acq_audio_i AFTER INSERT ON ar_acq_audio BEGIN UPDATE kmaps_cache_version SET version = strftime('%Y-%m-%dT%H:%M:%fZ','now'), updated_at = datetime('now') WHERE family = 'content'; END;
CREATE TRIGGER IF NOT EXISTS trg_kcv_ar_acq_audio_u AFTER UPDATE ON ar_acq_audio BEGIN UPDATE kmaps_cache_version SET version = strftime('%Y-%m-%dT%H:%M:%fZ','now'), updated_at = datetime('now') WHERE family = 'content'; END;
